// Loads the app's environment for every Slack channel script. Run from the app's runtime dir:
// ./.env is generated by `app up` (settings, no secrets) and points at the credentials file
// (APP_SECRETS, mode 600) which holds SLACK_APP_TOKEN / SLACK_BOT_TOKEN.
import dotenv from 'dotenv';
dotenv.config({ path: process.env.APP_ENV || '.env' });
if (process.env.APP_SECRETS) dotenv.config({ path: process.env.APP_SECRETS });
